script:
frappe.ui.form.on('Employee', {
    date_of_joining: function(frm) {
        if (frm.doc.date_of_joining) {
            let probation_end = frappe.datetime.add_months(frm.doc.date_of_joining, 6);
            frm.set_value('custom_probation_end_date', probation_end);
        }
    }
});

frappe.ui.form.on('Employee', {
    refresh: function(frm) {
        frm.toggle_display('naming_series', false);
        frm.set_df_property('naming_series', 'hidden', 1);
        if (frm.fields_dict.naming_series) {
            frm.fields_dict.naming_series.$wrapper.hide();
        }
    },
    onload_post_render: function(frm) {
        frm.toggle_display('naming_series', false);
        if (frm.fields_dict.naming_series) {
            frm.fields_dict.naming_series.$wrapper.hide();
        }
    },
    before_save: function(frm) {
        if (!frm.doc.naming_series) {
            frm.set_value('naming_series', 'HR-EMP-');
        }
    }
});

frappe.ui.form.on('Employee', {
    refresh: function(frm) {
        
        // ==========================================
        // 1. RULES FOR HR MANAGERS / HR USERS
        // ==========================================
        if (frappe.user.has_role('HR User') || frappe.user.has_role('HR Manager') || frappe.user.has_role('System Manager')) {
            
            // HR MUST fill these core fields to create the profile
            frm.set_df_property('first_name', 'reqd', 1);
            frm.set_df_property('company', 'reqd', 1);
            frm.set_df_property('date_of_joining', 'reqd', 1);
            frm.set_df_property('designation', 'reqd', 1);
            frm.set_df_property('department', 'reqd', 1);
            frm.set_df_property('employment_type', 'reqd', 1);

            // Make sure these are NOT mandatory for HR 
            // (Because the Employee will fill these later, or they are in your custom forms)
            frm.set_df_property('cell_number', 'reqd', 0);
            frm.set_df_property('personal_email', 'reqd', 0);
            frm.set_df_property('current_address', 'reqd', 0);
            frm.set_df_property('blood_group', 'reqd', 0);
            frm.set_df_property('emergency_phone_number', 'reqd', 0);
            frm.set_df_property('bank_name', 'reqd', 0);
            frm.set_df_property('bank_ac_no', 'reqd', 0);
            
            // Optional: You can hide the Bio/Health tabs from HR to make the form cleaner
            frm.set_df_property('bio', 'hidden', 1);
            frm.set_df_property('health_details', 'hidden', 1);
        } 
        
        // ==========================================
        // 2. RULES FOR THE NEW EMPLOYEE (Self Service)
        // ==========================================
        else if (frappe.user.has_role('Employee Self Service')) {
            
            // Lock down HR fields so the employee cannot change their own Job Title/Company
            frm.set_df_property('company', 'read_only', 1);
            frm.set_df_property('date_of_joining', 'read_only', 1);
            frm.set_df_property('designation', 'read_only', 1);
            frm.set_df_property('department', 'read_only', 1);
            frm.set_df_property('employment_type', 'read_only', 1);

            // Make basic contact info mandatory for the Employee to fill on their profile
            frm.set_df_property('cell_number', 'reqd', 1);
            frm.set_df_property('personal_email', 'reqd', 1);
            frm.set_df_property('blood_group', 'reqd', 1);
            frm.set_df_property('emergency_phone_number', 'reqd', 1);
            frm.set_df_property('person_to_be_contacted', 'reqd', 1);
            
            // NOTE: Bank, PF, and ESI are NOT made mandatory here because your 
            // custom forms (Form 11, ESI Enrollment) handle that data collection!
        }
    }
});

frappe.ui.form.on("Employee", {
    refresh: function(frm) {

        if (!frm.fields_dict.custom_policy_documents) {
            return;
        }

        let wrapper = frm.fields_dict.custom_policy_documents.$wrapper;

        wrapper.html("Loading policy documents...");

        frappe.call({
            method: "hrms_custom.api.get_employee_policies",
            args: {
                employee: frm.doc.name
            },
            callback: function(r) {

                let policies = r.message || [];

                if (!policies.length) {
                    wrapper.html("No policy documents available.");
                    return;
                }

                let html = "<table class='table table-bordered'>";
                html += "<thead><tr><th>Policy Name</th><th>Document</th></tr></thead>";
                html += "<tbody>";

                policies.forEach(function(policy) {

                    html += "<tr>";
                    html += "<td>" + (policy.policy_name || "") + "</td>";

                    if (policy.policy_pdf) {
                        html += "<td><a href='" + policy.policy_pdf + "' target='_blank'>View PDF</a></td>";
                    } else {
                        html += "<td>-</td>";
                    }

                    html += "</tr>";
                });

                html += "</tbody></table>";

                wrapper.html(html);
            },
            error: function() {
                wrapper.html("Failed to load policy documents.");
            }
        });
    }
});

frappe.ui.form.on('ESI EPF Enrollment', {
    employee: function(frm) {
        if (!frm.doc.employee) return;
        frappe.call({
            method: "hrms_custom.hrms_custom.doctype.esi_epf_enrollment.esi_epf_enrollment.get_employee_snapshot",
            args: { employee: frm.doc.employee },
            callback: function(r) {
                if (r.message) {
                    frm.set_value('employee_name', r.message.employee_name);
                    frm.set_value('date_of_birth', r.message.date_of_birth);
                    frm.set_value('date_of_joining', r.message.date_of_joining);
                    frm.set_value('gender', r.message.gender);
                    frm.set_value('department', r.message.department);
                    frm.set_value('designation', r.message.designation);
                    frm.set_value('bank_name', r.message.bank_name);
                    frm.set_value('account_number', r.message.account_number);
                    frm.set_value('ifsc_code', r.message.ifsc_code);
                    frm.refresh_fields();
                }
            }
        });
    },

    refresh: function(frm) {
        if (frm.doc.docstatus === 1) {
            frm.add_custom_button(__('Download Form 11 PDF'), function() {
                window.open(
                    frappe.urllib.get_full_url(
                        "/api/method/frappe.utils.print_format.download_pdf?doctype=ESI EPF Enrollment&name="
                        + encodeURIComponent(frm.doc.name)
                        + "&format=Standard&no_letterhead=0"
                    )
                );
            });
        }
    }
});

frappe.ui.form.on('Employee Onboarding', {
    company: function(frm) {
        if (!frm.doc.company) {
            frm.set_value('custom_last_employee_id', '');
            frm.set_value('custom_employee_id_', '');
            return;
        }

        frappe.call({
            method: 'hrms_custom.api.get_last_employee_id',
            args: {
                company: frm.doc.company
            },
            callback: function(r) {
                if (r.message) {
                    let last_id = r.message.last_id || 'No employees yet';
                    let next_id = r.message.next_id || '';

                    // Show last ID
                    frm.set_value('custom_last_employee_id', last_id);

                    // Auto fill next ID
                    if (next_id) {
                        frm.set_value('custom_employee_id_', next_id);
                        frappe.show_alert({
                            message: `Last ID: ${last_id} → Next ID: ${next_id}`,
                            indicator: 'green'
                        }, 5);
                    }
                }
            }
        });
    },

    // Also trigger on form load if company already set
    onload: function(frm) {
        if (frm.doc.company && !frm.doc.custom_employee_id_) {
            frm.trigger('company');
        }
    }
});

frappe.ui.form.on("Employee", {
    job_applicant: function(frm) {
        if (!frm.doc.job_applicant) return;

        let field_mapping = {
            "applicant_name": "employee_name",
            "phone_number": "cell_number",
            "custom_personal_email": "personal_email",
            "custom_date_of_birth": "date_of_birth",
            "custom_father_spouse_name": "custom_father_name",
            "custom_permanent_address": "permanent_address",
            "custom_current_address": "current_address",
            "custom_aadhar_number": "custom_aadhaar_number",
            "custom_pan_number": "pan_number",
            "custom_bank_account_number": "bank_ac_no",
            "custom_bank_name": "bank_name",
            "custom_bank_account_holder_name": "custom_name_as_per_bank",
            "custom_ifsc_code": "ifsc_code",
            "custom_uan_number": "custom_uan",
            "custom_spouse_name": "custom_spouse_name",
            "custom_blood_group": "blood_group",
            "custom_religion": "custom_religion",
            "designation": "designation",
            "custom_emergency_contact_name": "person_to_be_contacted",
            "custom_emergency_contact_number": "emergency_phone_number"
        };

        // Value translation for mismatched Select options
        let value_mapping = {
            "marital_status": {
                "Unmarried": "Single",
                "Single": "Single",
                "Married": "Married",
                "Divorced": "Divorced",
                "Widowed": "Widowed"
            }
        };

        let attachment_mapping = [
            { src: "custom_aadhar_upload", doc_type: "Aadhar", card_field: "custom_aadhar_number" },
            { src: "custom_pan_upload", doc_type: "PAN Card", card_field: "custom_pan_number" },
            { src: "custom_bank_passbook", doc_type: "Bank Passbook / Cancelled Cheque", card_field: "custom_bank_account_number" },
            { src: "custom_passport_photo", doc_type: "Passport Photo", card_field: null },
            { src: "custom_10th_marksheet", doc_type: "10th Marksheet", card_field: null },
            { src: "custom_12th_marksheet", doc_type: "12th Marksheet", card_field: null },
            { src: "custom_ug_certificate", doc_type: "Degree Certificate", card_field: null },
            { src: "custom_pg_certificate", doc_type: "PG Degree Certificate", card_field: null },
            { src: "custom_experience_certificate", doc_type: "Experience Certificate", card_field: null },
            { src: "custom_last_salary_slip", doc_type: "Last Salary Slip", card_field: null },
            { src: "resume_attachment", doc_type: "Resume / CV", card_field: null },
            { src: "custom_relieving_letter", doc_type: "Relieving Letter", card_field: null },
            { src: "custom_appointment_offer_letter", doc_type: "Appointment/Offer Letter", card_field: null }
        ];

        frappe.db.get_doc("Job Applicant", frm.doc.job_applicant).then(applicant_doc => {

            let filled = [];

            for (let src in field_mapping) {
                let target = field_mapping[src];
                let value = applicant_doc[src];

                if (value !== undefined && value !== null && value !== "") {

                    // Apply value translation if defined for this target field
                    if (value_mapping[target] && value_mapping[target][value] !== undefined) {
                        value = value_mapping[target][value];
                    }

                    if (!frm.doc[target]) {
                        frm.set_value(target, value);
                        filled.push(target);
                    }
                }
            }

            let docs_added = 0;
            attachment_mapping.forEach(map => {
                let file_url = applicant_doc[map.src];
                if (file_url) {
                    let exists = (frm.doc.employee_documents || []).some(
                        row => row.document_type === map.doc_type
                    );

                    if (!exists) {
                        let row = frm.add_child("employee_documents");
                        row.document_type = map.doc_type;
                        row.file = file_url;
                        if (map.card_field && applicant_doc[map.card_field]) {
                            row.card_number = applicant_doc[map.card_field];
                        }
                        docs_added++;
                    }
                }
            });

            if (docs_added > 0) {
                frm.refresh_field("employee_documents");
            }

            frappe.show_alert({
                message: "Auto-filled " + filled.length + " fields and " + docs_added + " documents from Job Applicant",
                indicator: "green"
            });
        });
    }
});

frappe.ui.form.on('Employee Onboarding', {
    refresh: function(frm) {
        let manager_fields = [
            "custom_desktop_or_laptop", "custom_sim_card", 
            "custom_email_id", "custom_email_replacement_name", "custom_software_access", 
            "custom_id_card", "custom_business_card", "custom_biometric_access", 
            "custom_tech_excel_access", "custom_crm_platform_access", 
            "custom_sales_tracker_access", "custom_portfolio_plus_access", 
            "custom_kyc_individual_link", "custom_novac_id_login"
        ];

        let hr_fields = ["employee_name", "date_of_joining", "department", "designation", "employee_grade"];

        let is_hr_manager = frappe.user_roles.includes("HR Manager");
        let is_hr_user = frappe.user_roles.includes("HR User");

        if (is_hr_manager || is_hr_user) {
            // For HR Roles (Even if they are also Hiring Manager)
            manager_fields.forEach(f => {
                if (frm.fields_dict[f]) {
                    frm.set_df_property(f, 'reqd', 0); // NOT mandatory
                    if (!frm.is_new()) {
                        frm.set_df_property(f, 'read_only', 1);
                    }
                }
            });

            hr_fields.forEach(f => {
                if (frm.fields_dict[f]) {
                    frm.set_df_property(f, 'reqd', 1); // Mandatory for HR
                }
            });
        } else {
            // For Non-HR Roles (e.g., Hiring Manager only)
            manager_fields.forEach(f => {
                if (frm.fields_dict[f]) {
                    frm.set_df_property(f, 'reqd', 1); // Mandatory
                }
            });
        }
    }
});
